use super::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128,maximum:u64){assert!(p.fits(*bank));assert!(work<=u128::from(maximum));*fuel=fuel.checked_sub(u64::try_from(work).unwrap()).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]fn actual_ordered_shared_birth_null_and_release_keep_input_and_exact_work(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();for grant in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:SharedOwner::<String>::allocation_bytes()-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let turn=SharedOwner::admit(input.take().unwrap(),grant, &mut None);assert_eq!(turn.work,u128::from(row["deniedWork"].as_u64().unwrap()));let(_,original)=turn.result.err().unwrap();assert_eq!(original.as_ptr(),pointer);input=Some(original)}
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||SharedOwner::admit(input.take().unwrap(),RetainedCloneGrant{maximum_items:1,..bank}, &mut None)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,u128::from(row["nullWork"].as_u64().unwrap()));fuel-=u64::try_from(turn.work).unwrap();let(_,original)=turn.result.err().unwrap();assert_eq!(original.as_ptr(),pointer);input=Some(original);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||SharedOwner::admit(input.take().unwrap(),RetainedCloneGrant{maximum_items:1,..bank}, &mut None));let(mut owner,p)=turn.result.map_err(|(error,_)|error).unwrap();assert_eq!(turn.work,u128::from(row["admitWork"].as_u64().unwrap()));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work,row["admitWork"].as_u64().unwrap());assert_eq!(owner.deref().as_ptr(),pointer);assert_eq!(serde_json::to_value(owner.deref()).unwrap(),row["value"]);
 let denied=owner.release_step(RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(denied.result.unwrap().progress,Default::default());assert_eq!(owner.deref().as_ptr(),pointer);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.release_step(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,u128::from(row["releaseWork"].as_u64().unwrap()));let released=turn.result.unwrap();assert_eq!(heap,(released.progress.retained_capacity_bytes,released.progress.released_bytes));post(&mut bank,&mut fuel,released.progress,turn.work,row["releaseWork"].as_u64().unwrap());assert!(owner.terminal_is_empty());assert_eq!(owner.release_step(Default::default()).work,u128::from(row["cachedWork"].as_u64().unwrap()));let mut close=crate::retirement::controlled::ControlledRetirement::new(released.value.unwrap()).map_err(|(error,_)|error).unwrap();let mut scratch=crate::bank::scratch();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let maximum=close.next_computational_work(bank.maximum_copy_bytes).unwrap();let g=RetainedCloneGrant{maximum_items:1,..bank};let((turn,_),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::bank::once(&mut scratch,g,maximum,|effect|close.step(effect)));let step=turn.result.unwrap();assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));post(&mut bank,&mut fuel,step.progress(),turn.work,maximum);}assert!(close.terminal_is_empty());}

#[test]
fn original_ordered_shared_slot_denials_keep_the_same_source() {
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();
 for axis in law["slotDenials"].as_array().unwrap(){
  let mut input=Some(law["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut target=None;let mut actual=None;let d=SharedOwner::<String>::source_admission_demand().unwrap();
  let mut g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:0,maximum_depth:d.depth};
  match axis.as_str().unwrap(){"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes-=1,"capacity"=>g.maximum_capacity_bytes-=1,"depth"=>g.maximum_depth-=1,_=>unreachable!()}
  let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||SharedOwner::admit_from(&mut input,&mut target,g,&mut actual));assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(turn.work,0);assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(target.is_none());assert!(actual.is_none());assert_eq!(heap,(0,0));
 }
 let mut input=Some(law["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut target=None;let mut actual=None;let d=SharedOwner::<String>::source_admission_demand().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:usize::MAX,maximum_depth:d.depth};
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||SharedOwner::admit_from(&mut input,&mut target,g,&mut actual)));assert!(turn.result.is_err());assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(target.is_none());
 actual=None;let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||SharedOwner::admit_from(&mut input,&mut target,g,&mut actual));let p=turn.result.unwrap().progress();assert!(input.is_none());assert_eq!(target.as_ref().unwrap().deref().as_ptr(),pointer);assert_eq!(turn.work,u128::from(law["slotWork"].as_u64().unwrap()));assert_eq!(heap,(p.retained_capacity_bytes,0));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(actual,Some(d.capacity_bytes));let mut target=target.unwrap();let output=target.release_step(g).result.unwrap().value.unwrap();assert_eq!(output.as_ptr(),pointer);assert!(target.terminal_is_empty());
}
